Json::Value Orders::toJson() const
{
    Json::Value ret;

    if(getId())
    {

        ret["id"]=getValueOfId();

    }
    else
    {
        ret["id"]=Json::Value();
    }

    if(getUserId())
    {

        ret["user_id"]=getValueOfUserId();

    }
    else
    {
        ret["user_id"]=Json::Value();
    }

    if(getEventId())
    {

        ret["event_id"]=getValueOfEventId();

    }
    else
    {
        ret["event_id"]=Json::Value();
    }

    if(getEmail())
    {

        ret["email"]=getValueOfEmail();

    }
    else
    {
        ret["email"]=Json::Value();
    }

    if(getAmount())
    {

        ret["amount"]=(Json::Int64)getValueOfAmount();

    }
    else
    {
        ret["amount"]=Json::Value();
    }

    if(getCurrency())
    {

        ret["currency"]=getValueOfCurrency();

    }
    else
    {
        ret["currency"]=Json::Value();
    }

    if(getReference())
    {

        ret["reference"]=getValueOfReference();

    }
    else
    {
        ret["reference"]=Json::Value();
    }

    if(getStatus())
    {

        ret["status"]=getValueOfStatus();

    }
    else
    {
        ret["status"]=Json::Value();
    }

    if(getPaidAt())
    {

        ret["paid_at"]=getPaidAt()->toDbStringLocal();

    }
    else
    {
        ret["paid_at"]=Json::Value();
    }

    if(getCreatedAt())
    {

        ret["created_at"]=getCreatedAt()->toDbStringLocal();

    }
    else
    {
        ret["created_at"]=Json::Value();
    }

    if(getUpdatedAt())
    {

        ret["updated_at"]=getUpdatedAt()->toDbStringLocal();

    }
    else
    {
        ret["updated_at"]=Json::Value();
    }

    return ret;
}

